/**
 * Get all permission claim values as an array
 */
export const getAllPermissionClaims = (): string[] =>
   Object.values(PERMISSION_CLAIMS);

/**
 * Get permission claims grouped by their group name
 */
export const getPermissionClaimsByGroup = (): Record<string, string[]> => {
   const groups: Record<string, string[]> = {};

   Object.entries(PERMISSION_CLAIM_METADATA).forEach(([key, metadata]) => {
      const groupName = metadata.groupName || "General";
      if (!groups[groupName]) {
         groups[groupName] = [];
      }
      groups[groupName].push(
         PERMISSION_CLAIMS[key as keyof typeof PERMISSION_CLAIMS]
      );
   });

   return groups;
};
